<?php $groupActive=$g['status']==='active';$usage=$g['usage']; ?>
<article class="pig-ref-card<?=$groupActive?'':' is-inactive'?>" data-pig-ref-group="<?=e($g['code'])?>">
<div class="pig-ref-card__head"><img src="<?=e(asset_url('illustrations/livestock/'.$g['illustration'].'.svg'))?>" width="72" height="54" alt="" aria-hidden="true"><div><span class="pig-ref-card__code">Groupe <?=e($g['code'])?></span><h4><?=e($g['name'])?></h4><p class="pig-ref-card__age"><i class="bi bi-hourglass-split" aria-hidden="true"></i> <?=e($groupActive?$g['age_label']:'Dès '.$g['min_age_months'].' mois · désactivé')?></p></div></div>
<?php if($g['description']): ?><p class="pig-ref-card__desc"><?=e($g['description'])?></p><?php endif; ?>
<ul class="pig-ref-capabilities" aria-label="Opérations autorisées"><?php foreach(PigGroupService::CAPABILITIES as $key=>[$label,$icon]): ?><li class="<?=$g[$key]?'is-on':'is-off'?>"><i class="bi <?=$g[$key]?e($icon):'bi-dash-circle'?>" aria-hidden="true"></i> <?=e($label)?><span class="sr-only"><?=$g[$key]?' : autorisé':' : non autorisé'?></span></li><?php endforeach; ?></ul>
<dl class="pig-ref-usage"><div><dt>Lots</dt><dd><?=(int)$usage['lots']?></dd></div><div><dt>Porcs</dt><dd><?=(int)$usage['heads']?></dd></div><div class="<?=$usage['pending']?'is-warning':''?>"><dt>À vérifier</dt><dd><?php if($usage['pending']): ?><a href="<?=e(base_url('livestock/pigs?filter=pending'))?>"><?=(int)$usage['pending']?></a><?php else: ?>0<?php endif; ?></dd></div></dl>
<?php if($canAdmin): ?>
<footer class="pig-ref-card__actions">
<button type="button" class="btn-secondary" data-workspace-modal-open="pig-group-edit-<?=e($g['id'])?>"><i class="bi bi-pencil" aria-hidden="true"></i> Modifier</button>
<form method="post" action="<?=e(base_url('livestock/pigs/groups/'.$g['id'].'/status'))?>" data-pig-form data-pig-group-status data-group-id="<?=e($g['id'])?>" data-confirm="<?=$groupActive?'Désactiver le groupe '.e($g['code']).' ?':'Réactiver le groupe '.e($g['code']).' ?'?>"><?=csrf_field()?><input type="hidden" name="version" value="<?=e($g['version'])?>"><input type="hidden" name="status" value="<?=$groupActive?'inactive':'active'?>"><p class="app-alert app-alert-error" data-feed-error hidden role="alert"></p><button type="submit" class="btn-ghost" aria-describedby="pig-group-status-hint-<?=e($g['id'])?>"><i class="bi <?=$groupActive?'bi-pause-circle':'bi-play-circle'?>" aria-hidden="true"></i> <?=$groupActive?'Désactiver':'Réactiver'?></button></form>
<?php if(!$g['reference_count']): ?><form method="post" action="<?=e(base_url('livestock/pigs/groups/'.$g['id'].'/delete'))?>" data-pig-form data-pig-group-delete data-group-id="<?=e($g['id'])?>" data-confirm="Supprimer définitivement le groupe <?=e($g['code'])?> ? Il n’a jamais été utilisé."><?=csrf_field()?><input type="hidden" name="version" value="<?=e($g['version'])?>"><p class="app-alert app-alert-error" data-feed-error hidden role="alert"></p><button type="submit" class="btn-ghost pig-ref-delete"><i class="bi bi-trash" aria-hidden="true"></i> Supprimer</button></form><?php endif; ?>
<small class="pig-ref-card__hint" id="pig-group-status-hint-<?=e($g['id'])?>" data-pig-status-hint></small>
</footer>
<?php endif; ?>
</article>
